function faceHotelPerson(person,target){const dx=target.x-person.position.x,dz=target.z-person.position.z;if(Math.abs(dx)+Math.abs(dz)>.01)person.rotation.y=Math.atan2(dx,dz)+Math.PI}
function updateHotelPeople(dt){
 const now=performance.now()*.001;
 for(const person of hotelPeople){
  if(person===hotelKeyCourier)continue;
  const data=person.userData;data.wait-=dt;
  const delta=data.target.clone().sub(person.position);delta.y=0;
  if(delta.length()<.12){
   faceHotelPerson(person,camera.position);
   if(data.wait<=0){const angle=Math.random()*Math.PI*2,distance=.35+Math.random()*data.radius;data.target.copy(data.home).add(new THREE.Vector3(Math.cos(angle)*distance,0,Math.sin(angle)*distance));data.wait=1.5+Math.random()*3.5}
  }else{
   const direction=delta.normalize();person.position.add(direction.multiplyScalar(data.speed*dt));faceHotelPerson(person,data.target);
   const stride=Math.sin(now*7+data.phase)*.42,arms=person.children.filter(child=>child.name==='arm'),legs=person.children.filter(child=>child.name==='leg');
   arms.forEach((limb,index)=>limb.rotation.x=(index?1:-1)*stride);legs.forEach((limb,index)=>limb.rotation.x=(index?-1:1)*stride);person.position.y=Math.abs(Math.sin(now*7+data.phase))*.025;
  }
 }
}
