function addHotelHidingSpot(kind,x,z,width=1.85,depth=1.3){const color=kind==='wardrobe'?0x39271f:0x2d2926,trim=kind==='wardrobe'?0x6c4c32:0x55504a,parts=[];parts.push(box(`hideable ${kind} back`,[x,1.5,z-depth/2],[width,3,.16],color,true));parts.push(box(`hideable ${kind} left side`,[x-width/2,1.5,z],[.16,3,depth],color,true));parts.push(box(`hideable ${kind} right side`,[x+width/2,1.5,z],[.16,3,depth],color,true));parts.push(box(`hideable ${kind} top`,[x,2.94,z],[width,.14,depth],trim,false));parts.push(box(`hideable ${kind} floor`,[x,.08,z],[width,.14,depth],0x171414,false));const left=box(`hideable ${kind} left door`,[x-width*.255,1.48,z+depth/2],[width*.47,2.82,.11],color,false),right=box(`hideable ${kind} right door`,[x+width*.255,1.48,z+depth/2],[width*.47,2.82,.11],color,false);left.rotation.y=-.34;right.rotation.y=.34;parts.push(left,right);for(const knobX of [x-.12,x+.12]){const knob=sphere(`${kind} brass handle`,[knobX,1.45,z+depth/2+.09],.055,0xc5a65d);parts.push(knob)}const trigger=interactive([x,1.5,z+depth/2+.38],[width+1,3.2,.9],8,'hotel-hide',kind),spot={kind,trigger,parts,x,z,leftDoor:left,rightDoor:right,leftClosed:left.rotation.y,rightClosed:right.rotation.y,hidePosition:new THREE.Vector3(x,1.25,z),exitPosition:new THREE.Vector3(x,1.7,z+depth/2+1.05),lookTarget:new THREE.Vector3(x,1.35,z+4),destroyed:false};trigger.userData.hideSpot=spot;hotelHideSpots.push(spot);objectLabel(`${kind.toUpperCase()} · E TO HIDE`,[x,3.35,z+depth/2+.25],.34);return spot}
